INSERT INTO versiones_firmware (id,version,chip,tipo_dispositivo,descripcion,manifiesto,directorio,ubicacion_archivo,publicado,descontinuado,creado_por)
SELECT (SELECT COALESCE(MAX(id),0)+1 FROM versiones_firmware),'1.0.3','ESP32-S3','sensores',
'Las credenciales WiFi/MQTT y asignaciones enviadas desde la app se verifican en NVS (se relee cada clave) antes de responder YAKU_PROVISIONING_OK; si la escritura falla se responde error en vez de perderlas al reiniciar. Buffer serie de 4096 bytes para la configuracion completa. Conserva las mejoras de EMA y publicacion de 1.0.2.',
'{"schema_version": 1, "version": "1.0.3", "chip": "ESP32-S3", "tipo_dispositivo": "sensores", "source_sha256": "e466c0194d5e059da606dc1c32913e37d1cf10eeba2bd255258458273d5cd816", "segmentos": [{"nombre": "esp32_s3.ino.bootloader.bin", "direccion": 0, "tamano": 19968, "sha256": "5f95cbc8b40b7a373f9cb85b534cb7a570cdad30ca27c7021775d830ca03276b"}, {"nombre": "esp32_s3.ino.partitions.bin", "direccion": 32768, "tamano": 3072, "sha256": "148b959cbff1c38aa8e1d5c0ba9d612c54997b945e56a63f41223eef650653a1"}, {"nombre": "boot_app0.bin", "direccion": 57344, "tamano": 8192, "sha256": "f94c5d786a7a8fab06ac5d10e33bf37711a6697636dc037559ea19cc410a17f0"}, {"nombre": "esp32_s3.ino.bin", "direccion": 65536, "tamano": 1021360, "sha256": "b543742d836a46b70a3b02e6290fa56a76aedb12ea457601703f9caefa3d4e6b"}]}'::jsonb,'esp32-s3-1.0.3','firmware_store/esp32-s3-1.0.3',true,false,
(SELECT MIN(id) FROM usuarios WHERE id_rol=1)
WHERE EXISTS (SELECT 1 FROM usuarios WHERE id_rol=1) AND NOT EXISTS
(SELECT 1 FROM versiones_firmware WHERE version='1.0.3' AND chip='ESP32-S3' AND tipo_dispositivo='sensores');
UPDATE versiones_firmware SET
descripcion='Las credenciales WiFi/MQTT y asignaciones enviadas desde la app se verifican en NVS (se relee cada clave) antes de responder YAKU_PROVISIONING_OK; si la escritura falla se responde error en vez de perderlas al reiniciar. Buffer serie de 4096 bytes para la configuracion completa. Conserva las mejoras de EMA y publicacion de 1.0.2.',
