directorio='esp32-s3-1.0.3',ubicacion_archivo='firmware_store/esp32-s3-1.0.3',publicado=true,descontinuado=false,fecha_descontinuado=NULL
WHERE version='1.0.3' AND chip='ESP32-S3' AND tipo_dispositivo='sensores';
UPDATE versiones_firmware SET publicado=false,descontinuado=true,fecha_descontinuado=COALESCE(fecha_descontinuado,now())
WHERE chip='ESP32-S3' AND tipo_dispositivo='sensores' AND version<>'1.0.3';
SELECT setval(pg_get_serial_sequence('versiones_firmware','id'),(SELECT MAX(id) FROM versiones_firmware));
